      `**Branch:** \`${opts.taskRepoBranch}\``,
      `**Last commit:** ${opts.lastCommitSha}`,
      "",
      "Agent terminated before completion — see handover.md.",
      "",
      "_This draft PR was opened by the post-hoc recovery routine._",
    ].join("\n");

    const createUrl = `https://api.github.com/repos/${owner}/${repo}/pulls`;
    const requestBody = JSON.stringify({
      title: prTitle,
      body: prBody,
      head: opts.taskRepoBranch,
      base: baseBranch,
      draft: true,
    });

    const created = curlJson([
      "-s", "-X", "POST",
      "-H", `Authorization: token ${opts.githubToken}`,
      "-H", "Accept: application/vnd.github+json",
      "-H", "Content-Type: application/json",
      "-d", requestBody,
      createUrl,
    ]) as { html_url?: string; number?: number };

    if (!created.html_url) {
      emitRecovery({ step: "open_draft_pr", error: `GitHub response missing html_url: ${JSON.stringify(created)}` });
      return undefined;
    }
    return created.html_url;
  } catch (e) {
    emitRecovery({ step: "find_or_open_draft_pr", error: String(e) });
    return undefined;
  }
}

// ── Handover writer ────────────────────────────────────────────────────────────

function writeHandover(opts: {
  handoverPath: string;
  taskId: string;
  taskRepoBranch: string;
  lastCommitSha: string;
  lastCommitMessage: string;
  terminalReason: string;
  prUrl: string | undefined;
  taskRepoPath: string;
}): void {
  const filesChanged = (() => {
    try {
      return execSync(
        `git -C "${opts.taskRepoPath}" diff --name-status $(git -C "${opts.taskRepoPath}" merge-base HEAD origin/main 2>/dev/null || echo HEAD~1) HEAD`,
        { encoding: "utf-8", stdio: "pipe" },
      ).trim() || "(no changes detected)";
    } catch {
      return "(could not determine changed files)";
    }
  })();

  const lines = [
    `# Handover — ${opts.taskId}`,
    "",
    `**Terminal reason:** ${opts.terminalReason}`,
    `**Branch:** ${opts.taskRepoBranch}`,
    `**Last commit:** ${opts.lastCommitSha} ${opts.lastCommitMessage}`,
    `**PR:** ${opts.prUrl ?? "(none opened)"}`,
    "",
    "## Files modified in this run",
    "",
    "```",
    filesChanged,
    "```",
    "",
    "## Next agent — read this first",
    "",
    "This handover was written by the post-hoc recovery routine.",
    "The agent that produced these commits did not have a chance to",
    "write a structured handover. Re-claim the task, read the diff,",
    "continue where the last commit left off. If a checkpoint",
    "handover.md was written by the agent itself it will appear",
    "above this stub — read it first.",
  ];

  mkdirSync(dirname(opts.handoverPath), { recursive: true });
  writeFileSync(opts.handoverPath, lines.join("\n"), "utf-8");
}

// ── Review-kind recovery ───────────────────────────────────────────────────────

/**
 * Lightweight recovery for review executors.
 *
 * The reviewer already posted its GitHub review (APPROVE or REQUEST_CHANGES)
 * before running out of turns or crashing — it just never got to write result.json.
 * Instead of the full impl recovery (commit/push/draft-PR/handover.md), we simply
 * look up the most recent substantive review on the PR and synthesize the correct
 * terminal_status from it. No git operations, no handover doc.
 */
async function recoverReview(opts: {
  implPrUrl: string | undefined;
  githubToken: string;
  taskId: string;
  featureId: string;
  resultPath: string;
  tokenUsage: { input: number; output: number } | undefined;
}): Promise<void> {
  const { implPrUrl, githubToken, taskId, featureId, resultPath, tokenUsage } = opts;

  type TerminalStatus = "passed" | "change_requested" | "escalate";
  let terminalStatus: TerminalStatus = "escalate";
  let notes = "reviewer exited without writing result.json — no prior GitHub review found";

  if (implPrUrl && githubToken) {
    try {
      const match = /github\.com\/([^/]+)\/([^/]+)\/pull\/(\d+)/.exec(implPrUrl);
      if (match) {
        const [, owner, repo, pullNumber] = match;
        const reviews = curlJson([
          "-s",
          "-H", `Authorization: Bearer ${githubToken}`,
          "-H", "Accept: application/vnd.github+json",
          `https://api.github.com/repos/${owner}/${repo}/pulls/${pullNumber}/reviews`,
        ]) as Array<{ state: string; submitted_at: string }>;

        const substantive = (Array.isArray(reviews) ? reviews : [])
          .filter((r) => r.state === "APPROVED" || r.state === "CHANGES_REQUESTED")
          .sort((a, b) => new Date(b.submitted_at).getTime() - new Date(a.submitted_at).getTime());

        if (substantive.length > 0) {
          if (substantive[0].state === "APPROVED") {
            terminalStatus = "passed";
            notes = "recovered: APPROVE already posted to GitHub before executor exited";
          } else {
            terminalStatus = "change_requested";
            notes = "recovered: REQUEST_CHANGES already posted to GitHub before executor exited";
          }
        }
      }
    } catch (e) {
      emitRecovery({ step: "fetch_github_reviews", task_id: taskId, feature_id: featureId, error: String(e) });
    }
  }

  try {
    const result = {
      terminal_status: terminalStatus,
      verdict: terminalStatus,
      confidence: terminalStatus === "escalate" ? 0.0 : 0.75,
      notes,
      ...(tokenUsage ? { token_usage: tokenUsage } : {}),
    } as unknown as ExecutorResult;
    mkdirSync(dirname(resultPath), { recursive: true });
    writeFileSync(resultPath, JSON.stringify(result), "utf-8");
    emitRecovery({ step: "wrote_result", terminal_status: terminalStatus, task_id: taskId, feature_id: featureId });
  } catch (e) {
    emitRecovery({ step: "write_result", task_id: taskId, feature_id: featureId, error: String(e) });
  }
}

// ── Public API ─────────────────────────────────────────────────────────────────

/**
 * Run the post-hoc recovery routine.
 *
 * For review-kind executors: checks GitHub for an already-posted review and
 * writes the matching terminal_status (passed/change_requested/escalate) directly.
 * No commit, no push, no draft PR, no handover doc.
 *
 * For impl-kind executors: commits any dirty work, pushes the branch, opens (or
 * reuses) a draft PR, writes handover.md, and writes terminal_status "blocked".
 *
 * No-op when the executor already wrote a valid result.json.
 */
export async function runRecovery(opts: RecoveryOpts): Promise<void> {
  const {
    spawnResult,
    taskId,
    featureId,
    taskRepoBranch,
    taskRepoPath,
    taskRepoUrl,
    githubToken,
    sshKeyPath,
    gitAuthorEmail,
    gitAuthorName,
    resultPath,
    tokenUsage,
    kind = "impl",
    implPrUrl,
    taskBaseBranch,
  } = opts;

  // ── 0. No-op when the executor already wrote a valid result ────────────────
  if (existsSync(resultPath)) {
    try {
      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as Record<string, unknown>;
      if (raw && typeof raw === "object" && typeof raw.terminal_status === "string") {
        const ts = raw.terminal_status;
        // impl: in_review with pr_url → clean completion
        if (kind === "impl" && ts === "in_review" && raw.pr_url) return;
        // review: any valid reviewer terminal_status → clean completion
        if (kind === "review" && (ts === "passed" || ts === "change_requested" || ts === "escalate")) return;
      }
    } catch { /* fall through to recovery */ }
  }

  // ── 0b. Review-kind: lightweight result recovery ───────────────────────────
  if (kind === "review") {
    await recoverReview({ implPrUrl, githubToken, taskId, featureId, resultPath, tokenUsage });
    return;
  }

  emitRecovery({ step: "start", task_id: taskId, feature_id: featureId });

  // Preserve existing blocked_reason if Claude produced a valid blocked result.
  let existingBlockedReason: string | undefined;
  let existingBlockedSuggestion: string | undefined;
  if (existsSync(resultPath)) {
    try {
      const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as unknown;
      if (isValidResult(raw)) {
        const r = raw as ExecutorResult;
        existingBlockedReason = r.blocked_reason;
        existingBlockedSuggestion = r.blocked_suggestion;
      }
    } catch { /* ignore */ }
  }

  const terminalReason = existingBlockedReason ?? detectTerminalReason(spawnResult);

  // ── 1. Commit dirty working tree ───────────────────────────────────────────
  let lastCommitSha = "";
  let lastCommitMessage = "";
  try {
    const porcelain = execSync(`git -C "${taskRepoPath}" status --porcelain`, {
      encoding: "utf-8",
      stdio: "pipe",
    }).trim();
    if (porcelain) {
      const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
      execSync(`git -C "${taskRepoPath}" add -A`, { env: gitEnv, stdio: "pipe" });
      execSync(
        `git -C "${taskRepoPath}" commit -m "wip(${taskId}): incomplete — agent terminated unexpectedly"`,
        { env: gitEnv, stdio: "pipe" },
      );
    }
    lastCommitSha = execSync(`git -C "${taskRepoPath}" rev-parse HEAD`, {
      encoding: "utf-8",
      stdio: "pipe",
    }).trim();
    lastCommitMessage = execSync(`git -C "${taskRepoPath}" log -1 --format=%s`, {
      encoding: "utf-8",
      stdio: "pipe",
    }).trim();
  } catch (e) {
    emitRecovery({ step: "commit_dirty_tree", error: String(e) });
  }

  // ── 2. Push branch (best-effort) ───────────────────────────────────────────
  try {
    execSync(`git -C "${taskRepoPath}" push origin "${taskRepoBranch}"`, {
      env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
      stdio: "pipe",
    });
  } catch (e) {
    emitRecovery({ step: "push_branch", error: String(e) });
  }

  // ── 3. Find or open draft PR ───────────────────────────────────────────────
  let prUrl: string | undefined;
  if (githubToken && taskRepoUrl) {
    prUrl = findOrOpenDraftPr({
      taskRepoUrl,
      taskRepoBranch,
      taskId,
      featureId,
      githubToken,
      lastCommitSha,
      taskBaseBranch,
    });
  }

  // ── 4. Write handover.md ───────────────────────────────────────────────────
  const handoverPath = join(dirname(resultPath), "handover.md");
  try {
    writeHandover({
      handoverPath,
      taskId,
      taskRepoBranch,
      lastCommitSha,
      lastCommitMessage,
      terminalReason,
      prUrl,
      taskRepoPath,
    });
  } catch (e) {
    emitRecovery({ step: "write_handover", error: String(e) });
  }

  // ── 5. Write result.json ───────────────────────────────────────────────────
  try {
    const result: ExecutorResult = {
      terminal_status: "blocked",
      blocked_reason: terminalReason,
      ...(existingBlockedSuggestion ? { blocked_suggestion: existingBlockedSuggestion } : {}),
      ...(tokenUsage ? { token_usage: tokenUsage } : {}),
      ...(prUrl ? { pr_url: prUrl } : {}),
      ...(existsSync(handoverPath) ? { handover_path: handoverPath } : {}),
    };
    mkdirSync(dirname(resultPath), { recursive: true });
    writeFileSync(resultPath, JSON.stringify(result), "utf-8");
    emitRecovery({ step: "wrote_result", terminal_status: "blocked", blocked_reason: terminalReason });
  } catch (e) {
    emitRecovery({ step: "write_result", error: String(e) });
  }
}

