/**
 * Unit tests for the Layer 1 post-hoc recovery routine (recovery.ts).
 *
 * Pure-function tests run without mocks.
 * runRecovery integration tests use real temp dirs for fs and vi.mock for
 * child_process (git and curl) to avoid real network calls.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { detectTerminalReason, isMaxTurnsExit, parseGitHubCoords } from "./recovery.js";

// ── Pure-function tests ───────────────────────────────────────────────────────

describe("isMaxTurnsExit", () => {
  it("returns true when stdout contains a max-turns error event", () => {
    const stdout = [
      '{"type":"assistant","message":{"content":[{"type":"text","text":"working..."}]}}',
      '{"type":"result","subtype":"error_max_turns","is_error":true}',
    ].join("\n");
    expect(isMaxTurnsExit(stdout)).toBe(true);
  });

  it("returns false when no max-turns event is present", () => {
    const stdout = [
      '{"type":"assistant","message":{"content":[{"type":"text","text":"done"}]}}',
      '{"type":"result","subtype":"success"}',
    ].join("\n");
    expect(isMaxTurnsExit(stdout)).toBe(false);
  });

  it("returns false for empty stdout", () => {
    expect(isMaxTurnsExit("")).toBe(false);
  });

  it("returns false for non-JSON lines", () => {
    expect(isMaxTurnsExit("plain text output\nno json here")).toBe(false);
  });
});

describe("detectTerminalReason", () => {
  it("returns executor_crashed when spawnResult is undefined", () => {
    expect(detectTerminalReason(undefined)).toBe("executor_crashed");
  });

  it("returns executor_spawn_error when spawn produced an error object", () => {
    const result = { stdout: "", status: null, signal: null, error: new Error("spawn failed") };
    expect(detectTerminalReason(result)).toBe("executor_spawn_error");
  });

  it("returns executor_signal_SIGTERM when process was signalled", () => {
    const result = { stdout: "", status: null, signal: "SIGTERM" };
    expect(detectTerminalReason(result)).toBe("executor_signal_SIGTERM");
  });

  it("returns max_turns_exceeded when stdout has the max-turns event", () => {
    const stdout = '{"type":"result","subtype":"error_max_turns","is_error":true}';
    const result = { stdout, status: 1, signal: null };
    expect(detectTerminalReason(result)).toBe("max_turns_exceeded");
  });

  it("returns executor_crashed for non-zero exit without signal or max-turns", () => {
    const result = { stdout: "", status: 1, signal: null };
    expect(detectTerminalReason(result)).toBe("executor_crashed");
  });

  it("returns result_not_written for zero-exit without a recognized reason (fallback)", () => {
    const result = { stdout: "some output", status: 0, signal: null };
    expect(detectTerminalReason(result)).toBe("result_not_written");
  });
});

describe("parseGitHubCoords", () => {
  it("parses SSH URL with .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("git@github.com:myorg/my-repo.git");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("parses SSH URL without .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("git@github.com:myorg/my-repo");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("parses HTTPS URL with .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("https://github.com/myorg/my-repo.git");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("parses HTTPS URL without .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("https://github.com/myorg/my-repo");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("throws for a non-GitHub URL", () => {
    expect(() => parseGitHubCoords("git@gitlab.com:myorg/my-repo.git")).toThrow();
  });
});

// ── runRecovery integration tests (real fs, mocked child_process) ─────────────

vi.mock("node:child_process", () => ({
  execSync: vi.fn(),
  spawnSync: vi.fn(),
  spawn: vi.fn(),
}));

import { execSync, spawnSync } from "node:child_process";
import { runRecovery } from "./recovery.js";

const mockExecSync = vi.mocked(execSync);
const mockSpawnSync = vi.mocked(spawnSync);

function makeTempDir(): string {
  return mkdtempSync(join(tmpdir(), "recovery-test-"));
}

function setupMocksForCleanRun(opts: {
  existingPrUrl?: string;
  gitStatusOutput?: string;
}): void {
  mockExecSync.mockImplementation((cmd: unknown) => {
    const c = String(cmd);
    // Return strings (not Buffers) so .trim() calls work correctly in recovery.ts
    if (c.includes("status --porcelain")) return opts.gitStatusOutput ?? "";
    if (c.includes("add -A")) return "";
    if (c.includes("commit -m")) return "";
    if (c.includes("push origin")) return "";
    if (c.includes("rev-parse HEAD")) return "abc1234def\n";
    if (c.includes("log -1")) return "wip: previous work\n";
    if (c.includes("diff --name-status")) return "M  src/index.ts\n";
    return "";
  });

  const prListResponse = opts.existingPrUrl
    ? [{ html_url: opts.existingPrUrl, number: 42 }]
    : [];
  mockSpawnSync.mockReturnValue({
    stdout: JSON.stringify(prListResponse),
    stderr: "",
    status: 0,
    pid: 1,
    output: [],
    signal: null,
  });
}

beforeEach(() => {
  vi.clearAllMocks();
});

describe("runRecovery — no-op when valid in_review result exists", () => {
  it("does not write result.json when in_review result already exists", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    writeFileSync(resultPath, JSON.stringify({ terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" }));

    setupMocksForCleanRun({});

    const writtenAt = (existsSync(resultPath) ? readFileSync(resultPath, "utf-8") : "");

    await runRecovery({
      spawnResult: { stdout: "", status: 0, signal: null },
      taskId: "T6",
      featureId: "agent-runtime-split",
      taskRepoBranch: "feature/agent-runtime-split-T6",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:myorg/my-repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "test@example.com",
      gitAuthorName: "Test Agent",
      resultPath,
    });

    // result.json must NOT be modified
    expect(readFileSync(resultPath, "utf-8")).toBe(writtenAt);
    // No git commands should have run
    expect(mockExecSync).not.toHaveBeenCalled();

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery — dirty tree → wip commit + blocked result", () => {
  it("commits uncommitted work and writes blocked result.json", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({ gitStatusOutput: "M  src/index.ts" });

    await runRecovery({
      spawnResult: { stdout: '{"type":"result","subtype":"error_max_turns"}', status: 1, signal: null },
      taskId: "T6",
      featureId: "agent-runtime-split",
      taskRepoBranch: "feature/agent-runtime-split-T6",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:myorg/my-repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "test@example.com",
      gitAuthorName: "Test Agent",
      resultPath,
      tokenUsage: { input: 1000, output: 200 },
    });

    // Commit must have been called
    const commitCall = mockExecSync.mock.calls.find(
      (call) => String(call[0]).includes("commit -m"),
    );
    expect(commitCall).toBeDefined();
    expect(String(commitCall![0])).toContain("wip(T6): incomplete");

    // result.json must be written with blocked status
    expect(existsSync(resultPath)).toBe(true);
    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("blocked");
    expect(result.blocked_reason).toBe("max_turns_exceeded");
    expect(result.token_usage).toEqual({ input: 1000, output: 200 });

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery — clean tree + existing PR → PR reused", () => {
  it("reuses an existing open PR without opening a new one", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    const existingPrUrl = "https://github.com/myorg/my-repo/pull/42";
    setupMocksForCleanRun({ existingPrUrl, gitStatusOutput: "" });

    await runRecovery({
      spawnResult: { stdout: "", status: 1, signal: null },
      taskId: "T6",
      featureId: "agent-runtime-split",
      taskRepoBranch: "feature/agent-runtime-split-T6",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:myorg/my-repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "test@example.com",
      gitAuthorName: "Test Agent",
      resultPath,
    });

    expect(existsSync(resultPath)).toBe(true);
    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.pr_url).toBe(existingPrUrl);

    // spawnSync was called to list PRs (found existing — no POST call)
    const spawnCalls = mockSpawnSync.mock.calls;
    expect(spawnCalls.length).toBe(1); // only the GET list call
    expect(String(spawnCalls[0][1])).toContain("pulls");

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery — step failures do not throw", () => {
  it("still writes result.json when push and PR open both fail", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    mockExecSync.mockImplementation((cmd: unknown) => {
      const c = String(cmd);
      if (c.includes("status --porcelain")) return "";
      if (c.includes("push origin")) throw new Error("push rejected");
      if (c.includes("rev-parse HEAD")) return "abc\n";
      if (c.includes("log -1")) return "last commit\n";
      if (c.includes("diff --name-status")) return "";
      return "";
    });

    // curl returns non-JSON to simulate PR open failure
    mockSpawnSync.mockReturnValue({
      stdout: "not-valid-json",
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    });

    await expect(
      runRecovery({
        spawnResult: undefined,
        taskId: "T6",
        featureId: "agent-runtime-split",
        taskRepoBranch: "feature/agent-runtime-split-T6",
        taskRepoPath: repoPath,
        taskRepoUrl: "git@github.com:myorg/my-repo.git",
        githubToken: "ghp_test",
        sshKeyPath: undefined,
        gitAuthorEmail: "test@example.com",
        gitAuthorName: "Test Agent",
        resultPath,
      }),
    ).resolves.toBeUndefined();

    // result.json must still be written despite failures
    expect(existsSync(resultPath)).toBe(true);
    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("blocked");

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery (review kind) — no-op when reviewer wrote valid result", () => {
  it("does not overwrite a passed result written by the reviewer", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    const original = JSON.stringify({ terminal_status: "passed", verdict: "passed", confidence: 0.92, notes: "all good" });
    writeFileSync(resultPath, original);

    await runRecovery({
      spawnResult: { stdout: "", status: 0, signal: null },
      taskId: "T1",
      featureId: "feature-kanban-board",
      taskRepoBranch: "feature/feature-kanban-board-T1",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:org/repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "reviewer@test.com",
      gitAuthorName: "Reviewer",
      resultPath,
      kind: "review",
    });

    expect(readFileSync(resultPath, "utf-8")).toBe(original);
    expect(mockExecSync).not.toHaveBeenCalled();

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery (review kind) — synthesize passed from GitHub APPROVE", () => {
  it("writes passed when GitHub reviews show APPROVED", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    mockSpawnSync.mockReturnValue({
      stdout: JSON.stringify([
        { state: "APPROVED", submitted_at: "2026-05-10T07:37:00Z" },
      ]),
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    });

    await runRecovery({
      spawnResult: { stdout: '{"type":"result","subtype":"error_max_turns"}', status: 1, signal: null },
      taskId: "T1",
      featureId: "feature-kanban-board",
      taskRepoBranch: "feature/feature-kanban-board-T1",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:org/repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "reviewer@test.com",
      gitAuthorName: "Reviewer",
      resultPath,
      kind: "review",
      implPrUrl: "https://github.com/tiendv89/digital-factory-ui/pull/35",
    });

    expect(existsSync(resultPath)).toBe(true);
    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("passed");
    expect(result.verdict).toBe("passed");
    expect(result.notes).toContain("APPROVE");
    expect(mockExecSync).not.toHaveBeenCalled();

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery (review kind) — synthesize change_requested from GitHub REQUEST_CHANGES", () => {
  it("writes change_requested when GitHub reviews show CHANGES_REQUESTED", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    mockSpawnSync.mockReturnValue({
      stdout: JSON.stringify([
        { state: "CHANGES_REQUESTED", submitted_at: "2026-05-10T07:37:00Z" },
      ]),
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    });

    await runRecovery({
      spawnResult: { stdout: "", status: 1, signal: null },
      taskId: "T1",
      featureId: "feature-kanban-board",
      taskRepoBranch: "feature/feature-kanban-board-T1",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:org/repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "reviewer@test.com",
      gitAuthorName: "Reviewer",
      resultPath,
      kind: "review",
      implPrUrl: "https://github.com/tiendv89/digital-factory-ui/pull/35",
    });

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("change_requested");
    expect(result.verdict).toBe("change_requested");

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery (review kind) — escalate when no prior GitHub review", () => {
  it("writes escalate when GitHub reviews list is empty", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    mockSpawnSync.mockReturnValue({
      stdout: JSON.stringify([]),
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    });

    await runRecovery({
      spawnResult: { stdout: "", status: 1, signal: null },
      taskId: "T1",
      featureId: "feature-kanban-board",
      taskRepoBranch: "feature/feature-kanban-board-T1",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:org/repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "reviewer@test.com",
      gitAuthorName: "Reviewer",
      resultPath,
      kind: "review",
      implPrUrl: "https://github.com/tiendv89/digital-factory-ui/pull/35",
    });

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("escalate");
    expect(result.confidence).toBe(0.0);
    expect(mockExecSync).not.toHaveBeenCalled();

    rmSync(dir, { recursive: true, force: true });
  });
});

describe("runRecovery — handover.md written next to result.json", () => {
  it("writes handover.md containing terminal reason and task ID", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const handoverPath = join(dir, "handover.md");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({ gitStatusOutput: "" });

    await runRecovery({
      spawnResult: { stdout: "", status: 1, signal: "SIGTERM" },
      taskId: "T6",
      featureId: "agent-runtime-split",
      taskRepoBranch: "feature/agent-runtime-split-T6",
      taskRepoPath: repoPath,
      taskRepoUrl: "git@github.com:myorg/my-repo.git",
      githubToken: "ghp_test",
      sshKeyPath: undefined,
      gitAuthorEmail: "test@example.com",
      gitAuthorName: "Test Agent",
      resultPath,
    });

    expect(existsSync(handoverPath)).toBe(true);
    const handover = readFileSync(handoverPath, "utf-8");
    expect(handover).toContain("T6");
    expect(handover).toContain("executor_signal_SIGTERM");

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.handover_path).toBe(handoverPath);

    rmSync(dir, { recursive: true, force: true });
  });
});

