49	function curlJson(args: string[]): unknown {
50	  const result = spawnSync("curl", args, {
51	    encoding: "utf-8",
52	    stdio: ["ignore", "pipe", "pipe"],
53	  });
54	  if (result.error) throw result.error;
55	  const stdout = result.stdout ?? "";
56	  if (!stdout.trim()) throw new Error(`curl returned empty response. stderr: ${result.stderr ?? ""}`);
57	  return JSON.parse(stdout);
58	}
