60	export function parseGitHubCoords(repoUrl: string): { owner: string; repo: string } {
61	  const sshMatch = /git@github\.com:([^/]+)\/([^.]+?)(?:\.git)?$/.exec(repoUrl);
62	  if (sshMatch) return { owner: sshMatch[1], repo: sshMatch[2] };
63	  const httpsMatch = /https?:\/\/github\.com\/([^/]+)\/([^/]+?)(?:\.git)?$/.exec(repoUrl);
64	  if (httpsMatch) return { owner: httpsMatch[1], repo: httpsMatch[2] };
65	  throw new Error(`Cannot parse GitHub coords from URL: "${repoUrl}"`);
66	}
