73	function findOrOpenDraftPr(opts: {
74	  taskRepoUrl: string;
75	  taskRepoBranch: string;
76	  taskId: string;
77	  featureId: string;
78	  githubToken: string;
79	  lastCommitSha: string;
80	  taskBaseBranch?: string;
81	}): string | undefined {
82	  try {
83	    const { owner, repo } = parseGitHubCoords(opts.taskRepoUrl);
84	    const encodedHead = encodeURIComponent(`${owner}:${opts.taskRepoBranch}`);
85	    const listUrl =
86	      `https://api.github.com/repos/${owner}/${repo}/pulls` +
87	      `?head=${encodedHead}&state=open`;
88	
89	    const prs = curlJson([
90	      "-s",
91	      "-H", `Authorization: token ${opts.githubToken}`,
92	      "-H", "Accept: application/vnd.github+json",
93	      listUrl,
94	    ]) as PrListItem[];
95	
96	    if (Array.isArray(prs) && prs.length > 0) return prs[0].html_url;
97	
98	    let baseBranch = opts.taskBaseBranch ?? "main";
99	    if (!opts.taskBaseBranch) {
100	      try {
101	        const repoMeta = curlJson([
102	          "-s",
103	          "-H", `Authorization: token ${opts.githubToken}`,
104	          "-H", "Accept: application/vnd.github+json",
105	          `https://api.github.com/repos/${owner}/${repo}`,
106	        ]) as { default_branch?: string };
107	        if (repoMeta.default_branch) baseBranch = repoMeta.default_branch;
108	      } catch { /* fall through to "main" */ }
109	    }
110	
111	    const prTitle = `[WIP] feat(${opts.featureId}/${opts.taskId}): agent terminated — draft PR`;
112	    const prBody = [
113	      `## Task: ${opts.taskId}`,
114	      "",
115	      `**Branch:** \`${opts.taskRepoBranch}\``,
116	      `**Last commit:** ${opts.lastCommitSha}`,
117	      "",
