121	    ].join("\n");
122	
123	    const created = curlJson([
124	      "-s", "-X", "POST",
125	      "-H", `Authorization: token ${opts.githubToken}`,
126	      "-H", "Accept: application/vnd.github+json",
127	      "-H", "Content-Type: application/json",
128	      "-d", JSON.stringify({
129	        title: prTitle,
130	        body: prBody,
131	        head: opts.taskRepoBranch,
132	        base: baseBranch,
