134	      }),
135	      `https://api.github.com/repos/${owner}/${repo}/pulls`,
136	    ]) as { html_url?: string };
137	
138	    if (!created.html_url) {
139	      emitRecovery({ step: "open_draft_pr", error: `GitHub response missing html_url: ${JSON.stringify(created)}` });
140	      return undefined;
141	    }
142	    return created.html_url;
143	  } catch (e) {
144	    emitRecovery({ step: "find_or_open_draft_pr", error: String(e) });
145	    return undefined;
146	  }
