161	      return execSync(
162	        `git -C "${opts.taskRepoPath}" diff --name-status $(git -C "${opts.taskRepoPath}" merge-base HEAD origin/main 2>/dev/null || echo HEAD~1) HEAD`,
163	        { encoding: "utf-8", stdio: "pipe" },
164	      ).trim() || "(no changes detected)";
165	    } catch {
