/**
 * Unit tests for the Layer 1 post-hoc recovery routine (recovery.ts).
 *
 * Pure-function tests run without mocks.
 * runRecovery integration tests use real temp dirs for fs and vi.mock for
 * child_process (git and curl) to avoid real network calls.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { detectTerminalReason, parseGitHubCoords } from "./recovery.js";

// ── Pure-function tests ───────────────────────────────────────────────────────

describe("detectTerminalReason", () => {
  it("returns executor_crashed when spawnResult is undefined", () => {
    expect(detectTerminalReason(undefined)).toBe("executor_crashed");
  });

  it("returns executor_spawn_error when spawn produced an error object", () => {
    const result = { stdout: "", status: null, signal: null, error: new Error("spawn failed") };
    expect(detectTerminalReason(result)).toBe("executor_spawn_error");
  });

  it("returns executor_signal_SIGTERM when process was signalled", () => {
    const result = { stdout: "", status: null, signal: "SIGTERM" };
    expect(detectTerminalReason(result)).toBe("executor_signal_SIGTERM");
  });

  it("returns executor_signal_SIGKILL when process was killed", () => {
    const result = { stdout: "", status: null, signal: "SIGKILL" };
    expect(detectTerminalReason(result)).toBe("executor_signal_SIGKILL");
  });

  it("returns executor_crashed for non-zero exit without signal", () => {
    const result = { stdout: "", status: 1, signal: null };
    expect(detectTerminalReason(result)).toBe("executor_crashed");
  });

  it("returns result_not_written for zero-exit without a recognized reason", () => {
    const result = { stdout: "some output", status: 0, signal: null };
    expect(detectTerminalReason(result)).toBe("result_not_written");
  });
});

describe("parseGitHubCoords", () => {
  it("parses SSH remote URLs", () => {
    const result = parseGitHubCoords("git@github.com:myorg/myrepo.git");
    expect(result).toEqual({ owner: "myorg", repo: "myrepo" });
  });

  it("parses SSH remote URLs without .git suffix", () => {
    const result = parseGitHubCoords("git@github.com:myorg/myrepo");
    expect(result).toEqual({ owner: "myorg", repo: "myrepo" });
  });

  it("parses HTTPS remote URLs", () => {
    const result = parseGitHubCoords("https://github.com/myorg/myrepo.git");
    expect(result).toEqual({ owner: "myorg", repo: "myrepo" });
  });

  it("parses HTTPS remote URLs without .git suffix", () => {
    const result = parseGitHubCoords("https://github.com/myorg/myrepo");
    expect(result).toEqual({ owner: "myorg", repo: "myrepo" });
  });

  it("parses SSH URLs with hyphens in repo name", () => {
    const result = parseGitHubCoords("git@github.com:my-org/my-repo.git");
    expect(result).toEqual({ owner: "my-org", repo: "my-repo" });
  });

  it("throws on unrecognised URLs", () => {
    expect(() => parseGitHubCoords("not-a-url")).toThrow("Cannot parse GitHub coords");
  });

  it("throws on non-GitHub SSH URLs", () => {
    expect(() => parseGitHubCoords("git@gitlab.com:org/repo.git")).toThrow("Cannot parse GitHub coords");
  });
});

// ── runRecovery integration tests (real fs, mocked child_process) ─────────────

vi.mock("node:child_process", () => ({
  execSync: vi.fn(),
  spawnSync: vi.fn(),
  spawn: vi.fn(),
}));

import { execSync, spawnSync } from "node:child_process";
import { runRecovery } from "./recovery.js";

const mockExecSync = vi.mocked(execSync);
const mockSpawnSync = vi.mocked(spawnSync);

function makeTempDir(): string {
  return mkdtempSync(join(tmpdir(), "hermes-recovery-test-"));
}

function setupMocksForCleanRun(opts: {
  existingPrUrl?: string;
  gitStatusOutput?: string;
}): void {
  mockExecSync.mockImplementation((cmd: unknown) => {
    const c = String(cmd);
    if (c.includes("status --porcelain")) return opts.gitStatusOutput ?? "";
    if (c.includes("add -A")) return "";
    if (c.includes("commit -m")) return "";
    if (c.includes("push origin")) return "";
    if (c.includes("rev-parse HEAD")) return "abc1234def\n";
    if (c.includes("log -1")) return "wip: previous work\n";
    if (c.includes("diff --name-status")) return "M  src/index.ts\n";
    return "";
  });

  const prListResponse = opts.existingPrUrl
    ? [{ html_url: opts.existingPrUrl, number: 42 }]
    : [];
  mockSpawnSync.mockReturnValue({
    stdout: JSON.stringify(prListResponse),
    stderr: "",
    status: 0,
    pid: 1,
    output: [],
    signal: null,
  });
}

beforeEach(() => {
  vi.clearAllMocks();
});

const BASE_OPTS = {
  taskId: "T5",
  featureId: "adding-hermes-executor",
  taskRepoBranch: "feature/adding-hermes-executor-T5",
  taskRepoUrl: "git@github.com:myorg/myrepo.git",
  githubToken: "ghp_test",
  sshKeyPath: undefined,
  gitAuthorEmail: "test@example.com",
  gitAuthorName: "Test Agent",
} as const;

// ── Short-circuit tests ───────────────────────────────────────────────────────

describe("runRecovery — no-op when valid in_review result exists", () => {
  it("does not overwrite result.json when in_review with pr_url already written", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    const original = JSON.stringify({ terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" });
    writeFileSync(resultPath, original);

    setupMocksForCleanRun({});

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 0, signal: null },
      taskRepoPath: repoPath,
      resultPath,
    });

    expect(readFileSync(resultPath, "utf-8")).toBe(original);
    expect(mockExecSync).not.toHaveBeenCalled();

    rmSync(dir, { recursive: true, force: true });
  });

  it("does not short-circuit when in_review but pr_url is absent", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    writeFileSync(resultPath, JSON.stringify({ terminal_status: "in_review" }));
    setupMocksForCleanRun({});

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 0, signal: null },
      taskRepoPath: repoPath,
      resultPath,
    });

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("blocked");

    rmSync(dir, { recursive: true, force: true });
  });
});

// ── Dirty tree commit tests ───────────────────────────────────────────────────

describe("runRecovery — dirty tree → wip commit + blocked result", () => {
  it("commits uncommitted work and writes blocked result.json", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({ gitStatusOutput: "M  src/index.ts" });

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: null },
      taskRepoPath: repoPath,
      resultPath,
    });

    const commitCall = mockExecSync.mock.calls.find(
      (call) => String(call[0]).includes("commit -m"),
    );
    expect(commitCall).toBeDefined();
    expect(String(commitCall![0])).toContain("wip(T5): incomplete");

    expect(existsSync(resultPath)).toBe(true);
    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("blocked");
    expect(result.blocked_reason).toBe("executor_crashed");

    rmSync(dir, { recursive: true, force: true });
  });

  it("does not commit when working tree is clean", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({ gitStatusOutput: "" });

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: null },
      taskRepoPath: repoPath,
      resultPath,
    });

    const commitCall = mockExecSync.mock.calls.find(
      (call) => String(call[0]).includes("commit -m"),
    );
    expect(commitCall).toBeUndefined();

    rmSync(dir, { recursive: true, force: true });
  });
});

// ── token_usage propagation ───────────────────────────────────────────────────

describe("runRecovery — token_usage included in blocked result", () => {
  it("includes token_usage in result.json when provided", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({});

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: null },
      taskRepoPath: repoPath,
      resultPath,
      tokenUsage: { input: 1000, output: 200 },
    });

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.token_usage).toEqual({ input: 1000, output: 200 });

    rmSync(dir, { recursive: true, force: true });
  });

  it("omits token_usage from result.json when not provided", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({});

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: null },
      taskRepoPath: repoPath,
      resultPath,
    });

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.token_usage).toBeUndefined();

    rmSync(dir, { recursive: true, force: true });
  });
});

// ── blocked_suggestion preservation ──────────────────────────────────────────

describe("runRecovery — blocked_suggestion preserved from existing result.json", () => {
  it("carries forward blocked_suggestion written by the agent before crash", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    writeFileSync(
      resultPath,
      JSON.stringify({
        terminal_status: "blocked",
        blocked_reason: "tests_failed",
        blocked_suggestion: "Fix type errors in src/index.ts before re-running.",
      }),
    );
    setupMocksForCleanRun({});

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: null },
      taskRepoPath: repoPath,
      resultPath,
    });

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.blocked_reason).toBe("tests_failed");
    expect(result.blocked_suggestion).toBe("Fix type errors in src/index.ts before re-running.");

    rmSync(dir, { recursive: true, force: true });
  });
});

// ── PR reuse tests ────────────────────────────────────────────────────────────

describe("runRecovery — existing PR reused", () => {
  it("reuses an existing open PR without creating a new one", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    const existingPrUrl = "https://github.com/myorg/myrepo/pull/42";
    setupMocksForCleanRun({ existingPrUrl, gitStatusOutput: "" });

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: null },
      taskRepoPath: repoPath,
      resultPath,
    });

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.pr_url).toBe(existingPrUrl);

    // Only one curl call to list PRs (found existing — no POST)
    expect(mockSpawnSync.mock.calls.length).toBe(1);
    expect(String(mockSpawnSync.mock.calls[0][1])).toContain("pulls");

    rmSync(dir, { recursive: true, force: true });
  });
});

// ── handover.md tests ─────────────────────────────────────────────────────────

describe("runRecovery — handover.md written", () => {
  it("writes handover.md containing task ID and terminal reason", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const handoverPath = join(dir, "handover.md");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({ gitStatusOutput: "" });

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: "SIGTERM" },
      taskRepoPath: repoPath,
      resultPath,
    });

    expect(existsSync(handoverPath)).toBe(true);
    const handover = readFileSync(handoverPath, "utf-8");
    expect(handover).toContain("T5");
    expect(handover).toContain("executor_signal_SIGTERM");

    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.handover_path).toBe(handoverPath);

    rmSync(dir, { recursive: true, force: true });
  });
});

// ── Non-throwing tests ────────────────────────────────────────────────────────

describe("runRecovery — step failures do not throw", () => {
  it("still writes result.json when push and PR open both fail", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    mockExecSync.mockImplementation((cmd: unknown) => {
      const c = String(cmd);
      if (c.includes("status --porcelain")) return "";
      if (c.includes("push origin")) throw new Error("push rejected");
      if (c.includes("rev-parse HEAD")) return "abc\n";
      if (c.includes("log -1")) return "last commit\n";
      if (c.includes("diff --name-status")) return "";
      return "";
    });

    // curl returns non-JSON to simulate PR open failure
    mockSpawnSync.mockReturnValue({
      stdout: "not-valid-json",
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    });

    await expect(
      runRecovery({
        ...BASE_OPTS,
        spawnResult: undefined,
        taskRepoPath: repoPath,
        resultPath,
      }),
    ).resolves.toBeUndefined();

    expect(existsSync(resultPath)).toBe(true);
    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("blocked");
    expect(result.blocked_reason).toBe("executor_crashed");

    rmSync(dir, { recursive: true, force: true });
  });

  it("still writes result.json when git status command throws", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    mockExecSync.mockImplementation((cmd: unknown) => {
      const c = String(cmd);
      if (c.includes("status --porcelain")) throw new Error("not a git repo");
      if (c.includes("diff --name-status")) return "";
      return "";
    });

    mockSpawnSync.mockReturnValue({
      stdout: JSON.stringify([]),
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    });

    await expect(
      runRecovery({
        ...BASE_OPTS,
        spawnResult: { stdout: "", status: 1, signal: null },
        taskRepoPath: repoPath,
        resultPath,
      }),
    ).resolves.toBeUndefined();

    expect(existsSync(resultPath)).toBe(true);
    const result = JSON.parse(readFileSync(resultPath, "utf-8"));
    expect(result.terminal_status).toBe("blocked");

    rmSync(dir, { recursive: true, force: true });
  });
});

// ── taskBaseBranch propagation ────────────────────────────────────────────────

describe("runRecovery — taskBaseBranch used for draft PR", () => {
  it("opens draft PR targeting taskBaseBranch when provided", async () => {
    const dir = makeTempDir();
    const resultPath = join(dir, "result.json");
    const repoPath = join(dir, "repo");
    mkdirSync(repoPath);

    setupMocksForCleanRun({ gitStatusOutput: "" });
    // Override to capture the PR creation body
    let capturedBody: string | undefined;
    mockSpawnSync.mockImplementation((cmd: unknown, args: unknown) => {
      const argArr = args as string[];
      // First call: list PRs (returns empty)
      if (argArr.some((a) => String(a).includes("?head="))) {
        return { stdout: "[]", stderr: "", status: 0, pid: 1, output: [], signal: null };
      }
      // Second call: create PR
      const bodyIdx = argArr.indexOf("-d");
      if (bodyIdx !== -1) capturedBody = argArr[bodyIdx + 1];
      return {
        stdout: JSON.stringify({ html_url: "https://github.com/myorg/myrepo/pull/99", number: 99 }),
        stderr: "",
        status: 0,
        pid: 1,
        output: [],
        signal: null,
      };
    });

    await runRecovery({
      ...BASE_OPTS,
      spawnResult: { stdout: "", status: 1, signal: null },
      taskRepoPath: repoPath,
      resultPath,
      taskBaseBranch: "feature/adding-hermes-executor",
    });

    expect(capturedBody).toBeDefined();
    const body = JSON.parse(capturedBody!);
    expect(body.base).toBe("feature/adding-hermes-executor");

    rmSync(dir, { recursive: true, force: true });
  });
});

